const syncLoyaltyPending = `-- name: SyncLoyaltyPending :many
WITH charges AS (
    SELECT p.customer_id, i.id AS invoice_id,
           sum(sum(p.amount_paisa)) OVER (PARTITION BY p.customer_id ORDER BY i.ad_datetime, i.number, i.id) AS cum
    FROM payments p JOIN invoices i ON i.id = p.invoice_id
    WHERE p.method = 'ON_ACCOUNT' AND i.status = 'ISSUED'
    GROUP BY p.customer_id, i.id
), repaid AS (
    SELECT customer_id, sum(amount_paisa) AS total FROM repayments WHERE voided_at IS NULL GROUP BY customer_id
), unpaid AS (
    SELECT DISTINCT ch.invoice_id FROM charges ch LEFT JOIN repaid r ON r.customer_id = ch.customer_id
    WHERE ch.cum > COALESCE(r.total, 0)
), wanted AS (
    SELECT e.id, CASE WHEN e.invoice_id IN (SELECT invoice_id FROM unpaid) THEN 'PENDING' ELSE 'DONE' END AS status
    FROM loyalty_entries e JOIN invoices i ON i.id = e.invoice_id
    WHERE e.kind = 'EARN' AND i.status = 'ISSUED'
      AND EXISTS (SELECT 1 FROM payments p WHERE p.invoice_id = i.id AND p.method = 'ON_ACCOUNT')
)
UPDATE loyalty_entries e SET status = w.status
FROM wanted w
WHERE e.id = w.id AND e.status <> w.status
RETURNING e.customer_id
`

// An EARN on an on-account bill counts (DONE) only while every on-account amount
// on the bill is paid off, oldest bill first per customer (credit allocation);
// otherwise it waits (PENDING). Sets every such entry to what it should be and
// returns the members whose card changed.
func (q *Queries) SyncLoyaltyPending(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, syncLoyaltyPending)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var customer_id uuid.UUID
		if err := rows.Scan(&customer_id); err != nil {
			return nil, err
		}
		items = append(items, customer_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateLoyaltySettings = `-- name: UpdateLoyaltySettings :one
UPDATE loyalty_settings
SET enabled = $1, stamps_per_reward = $2, min_spend_paisa = $3, reward_value_paisa = $4,
    expiry_months = $5, credit_bills_earn = $6, birthday_reward_paisa = $7, updated_at = now()
WHERE id
RETURNING id, enabled, stamps_per_reward, min_spend_paisa, reward_value_paisa, expiry_months, credit_bills_earn, birthday_reward_paisa, updated_at
`

type UpdateLoyaltySettingsParams struct {
	Enabled             bool  `json:"enabled"`
	StampsPerReward     int32 `json:"stamps_per_reward"`
	MinSpendPaisa       int64 `json:"min_spend_paisa"`
	RewardValuePaisa    int64 `json:"reward_value_paisa"`
	ExpiryMonths        int32 `json:"expiry_months"`
	CreditBillsEarn     bool  `json:"credit_bills_earn"`
	BirthdayRewardPaisa int64 `json:"birthday_reward_paisa"`
}

func (q *Queries) UpdateLoyaltySettings(ctx context.Context, arg UpdateLoyaltySettingsParams) (LoyaltySetting, error) {
	row := q.db.QueryRow(ctx, updateLoyaltySettings,
		arg.Enabled,
		arg.StampsPerReward,
		arg.MinSpendPaisa,
		arg.RewardValuePaisa,
		arg.ExpiryMonths,
		arg.CreditBillsEarn,
		arg.BirthdayRewardPaisa,
	)
	var i LoyaltySetting
	err := row.Scan(
		&i.ID,
		&i.Enabled,
		&i.StampsPerReward,
		&i.MinSpendPaisa,
		&i.RewardValuePaisa,
		&i.ExpiryMonths,
		&i.CreditBillsEarn,
		&i.BirthdayRewardPaisa,
		&i.UpdatedAt,
	)
	return i, err
}
